function startGame(){score=0;wave=1;lives=3;shots=[];enemies=[];enemyShots=[];particles=[];pickups=[];boss=null;spawnLeft=8;spawnTimer=.45;fireTimer=0;elapsed=0;combo=0;comboTimer=0;player={x:W/2,y:H-110,inv:1.5,power:1};target={x:W/2,y:H-110};mode='play';overlay.classList.add('hidden');pauseBtn.disabled=false;pauseBtn.textContent='Ⅱ';last=performance.now();}
function pauseGame(){if(mode!=='play')return;mode='pause';pointerDown=false;pauseBtn.textContent='▶';showOverlay('pause');}
function resumeGame(){if(mode!=='pause')return;mode='play';overlay.classList.add('hidden');pauseBtn.textContent='Ⅱ';last=performance.now();}
pauseBtn.onclick=()=>mode==='play'?pauseGame():mode==='pause'?resumeGame():null;
