function spawnEnemy(){const heavy=Math.random()<Math.min(.24,.08+wave*.012),zig=!heavy&&Math.random()<.38;const hp=heavy?3+Math.floor(wave/4):zig?2:1;enemies.push({x:rand(35,W-35),y:-35,hp,max:hp,type:heavy?'heavy':zig?'zig':'scout',phase:rand(0,7),speed:rand(56,90)+wave*4,fire:rand(1.5,3.8),age:0})}
function spawnBoss(){const level=Math.floor(wave/3);boss={x:W/2,y:-105,hp:54+level*20,max:54+level*20,age:0,fire:1.1,phase:0,entering:true};shake=8;flash=.4;tone(110,.5,'sawtooth',.07)}
function nextWave(){wave++;spawnLeft=7+Math.min(7,wave);spawnTimer=1.2;addBurst(W/2,120,C.cyan,24,1.3);tone(740,.2,'triangle',.04);if(wave%3===0){spawnLeft=0;spawnTimer=2.2;boss=null;}}
