function destroyEnemy(e){score+=e.type==='heavy'?180:e.type==='zig'?120:80;combo++;comboTimer=2.2;addBurst(e.x,e.y,e.type==='heavy'?C.yellow:C.pink,e.type==='heavy'?23:14,e.type==='heavy'?1.1:.8);tone(e.type==='heavy'?220:330,.07,'square',.025);if(Math.random()<.09)pickups.push({x:e.x,y:e.y,vy:72,age:0});}
