for(const s of stars){s.y+= (30+s.z*105)*dt;if(s.y>H){s.y=0;s.x=Math.random()*W}}
if(mode!=='play'){updateFx(dt);return}player.inv=Math.max(0,player.inv-dt);const speed=13*dt;player.x+=clamp(target.x-player.x,-speed*60,speed*60);player.y+=clamp(target.y-player.y,-speed*60,speed*60);player.x=clamp(player.x,24,W-24);player.y=clamp(player.y,H*.47,H-48);
