else{spawnTimer-=dt;if(spawnLeft>0&&spawnTimer<=0){spawnEnemy();spawnLeft--;spawnTimer=Math.max(.35,.88-wave*.025)}if(spawnLeft===0&&enemies.length===0){if(wave%3===0&&wave>1){spawnTimer-=dt;if(spawnTimer<=0&&!boss){spawnBoss()}}else if(!boss)nextWave()}}
